import { Accordion, Box, Flex, Separator, Text } from "@chakra-ui/react";
import { RasaCodeBlock } from "../../RasaCodeBlock";
import { useInspectorStore } from "../../store";
import { ReferenceTag } from "../../try-assistant/SkillSection/ReferenceTag";
import { skillEventVerbs } from "../../try-assistant/ConversationLog/Event/skillEventLabel";
import type { ConversationEvent } from "../../types";
import { CommonEventInfo, DetailView, EventAccordionItem, InfoField } from "./blocks";
import { resolveTriggeringMessage } from "./resolveTriggeringMessage";

export type SkillLifecycleEvent = ConversationEvent & { skillId: string };

interface SkillEventInfoProps {
  event: SkillLifecycleEvent;
  onClose: () => void;
}

export const SkillEventInfo = ({ event, onClose }: SkillEventInfoProps) => {
  const skillCatalog = useInspectorStore((s) => s.skillCatalog);
  const conversationList = useInspectorStore((s) => s.conversationList);
  const verb = skillEventVerbs[event.conversationEventType] ?? "activated";
  const triggerMessage = resolveTriggeringMessage(
    conversationList,
    event.metadata.triggering_user_message_timestamp,
  );
  const catalogSkill = skillCatalog?.[event.skillId];

  return (
    <DetailView title={`Skill ${verb}`} onClose={onClose}>
      <InfoField label="Skill ID">
        <Text textStyle="sm">{event.skillId}</Text>
      </InfoField>

      {catalogSkill && (
        <InfoField label="Name">
          <Text textStyle="sm">{catalogSkill.name ?? catalogSkill.id}</Text>
        </InfoField>
      )}

      {event.stepId && (
        <InfoField label="Step ID">
          <Text textStyle="sm">{event.stepId}</Text>
        </InfoField>
      )}

      {catalogSkill?.description && (
        <InfoField label="Description">
          <Text textStyle="sm">{catalogSkill.description}</Text>
        </InfoField>
      )}

      {catalogSkill && catalogSkill.tool_names.length > 0 && (
        <InfoField label="Available tools">
          <Flex gap="1.5" flexWrap="wrap" data-testid="skill-event-tools">
            {catalogSkill.tool_names.map((toolName) => (
              <ReferenceTag
                key={toolName}
                name={toolName}
                reference={{ kind: "tool", target: toolName }}
              />
            ))}
          </Flex>
        </InfoField>
      )}

      {catalogSkill && catalogSkill.referenced_skills.length > 0 && (
        <InfoField label="References">
          <Flex gap="1.5" flexWrap="wrap" data-testid="skill-event-references">
            {catalogSkill.referenced_skills.map((referencedSkillId) => (
              <ReferenceTag
                key={referencedSkillId}
                name={referencedSkillId}
                reference={{ kind: "skill", target: referencedSkillId }}
              />
            ))}
          </Flex>
        </InfoField>
      )}

      {triggerMessage && (
        <InfoField label="Trigger">
          <Text textStyle="sm" color="fg.muted" mb="1">
            User message
          </Text>
          <Box borderRadius="lg" overflow="hidden">
            <RasaCodeBlock code={triggerMessage} data-testid="skill-event-trigger" />
          </Box>
        </InfoField>
      )}

      <Separator mt="2" />
      <Accordion.Root collapsible multiple>
        <EventAccordionItem title="Event details" value="event-details">
          <CommonEventInfo event={event} />
        </EventAccordionItem>
      </Accordion.Root>
    </DetailView>
  );
};
